"use strict";

// Fictional dense network generated by index; no library or provider records.
const nodes = Array.from({ length: 50 }, (_, index) => ({
  workKey: `example:paper-${String(index).padStart(2, "0")}`,
  isSeed: index < 38,
  citationCount: (index * 37 + 11) % 640,
}));
const edges = [];
const seen = new Set();
function add(source, target) {
  const pair = `${source}:${target}`;
  if (source === target || seen.has(pair)) return;
  seen.add(pair);
  edges.push({ sourceWorkKey: nodes[source].workKey, targetWorkKey: nodes[target].workKey, type: "cites" });
}
const groups = [{ start: 0, size: 10 }, { start: 10, size: 10 }, { start: 20, size: 9 }, { start: 29, size: 9 }];
for (let index = 0; index < 38; index++) {
  const group = groups.find(value => index >= value.start && index < value.start + value.size);
  for (const offset of [1, 3]) add(index, group.start + (index - group.start + offset) % group.size);
  if (index < 16) add(index, group.start + (index - group.start + 5) % group.size);
}
for (let index = 38; index < 50; index++) {
  const group = groups[Math.floor((index - 38) / 3)];
  for (let neighbor = 0; neighbor < 4; neighbor++) add(index, group.start + (((index - 38) % 3) * 3 + neighbor) % group.size);
}
module.exports = { nodes, edges };
